            { id: "mmp-mhs-p066", label: "Transformasi Struktur Organisasi & Kompetensi SDM" },
            { id: "mmp-mhs-p067", label: "Alur Produksi Berita Digital" },
            { id: "mmp-mhs-p068", label: "Pengemasan Konten Multi Format" },
            { id: "mmp-mhs-p069", label: "Studi Kasus" },
            { id: "mmp-mhs-p071", label: "Kesimpulan" }
